#include <iostream>
#include <string>
using namespace std;

class Person {
protected:
    string name;
    int fish;
public:
    Person(string n, int f) : name(n), fish(f) {
        cout << "对象基类：" << name << endl;
    }
    ~Person() {
        cout << "对象基类走了" << endl;
    }
};

class Student : public Person {
public:
    Student(string n, int f) : Person(n, f) {
        cout << "子对象：" << name << " " << fish << " 条" << endl;
    }
    ~Student() {
        cout << "子对象走了" << endl;
    }
};

int main() {
    Student k("张三", 3);
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Person {
    string name;
protected:
    int fish;
public:
    Person(string n, int f) : name(n), fish(f) {}
    void showName() const {
        cout << "我们是" << name << "" << endl;
    }
};

class Student : public Person {
public:
    Student(string n, int f) : Person(n, f) {}
    void eat() {
        fish = fish + 1;
        cout << "处理了一条，现在 " << fish << " 条" << endl;
    }
};

int main() {
    Student k("张三", 3);
    k.showName();
    k.eat();
    k.eat();
    return 0;
}
